WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, pos, line.qty, line.price, line.promo FROM carts LATERAL VIEW POSEXPLODE(items) e AS pos, line) SELECT CASE WHEN qty >= 5 THEN 'PREMIUM' ELSE 'STANDARD' END AS qty_tier, CASE WHEN price >= 252 THEN 'LARGE' ELSE 'SMALL' END AS price_tier, promo, COUNT(CASE WHEN promo = 'SPRING10' THEN 1 END) AS spring10_count, PERCENTILE_APPROX(qty, ARRAY(0.25, 0.5, 0.75)) AS qty_quartiles, COUNT(*) FILTER (WHERE promo = 'SPRING10') AS spring10_rows FROM lines GROUP BY ROLLUP (CASE WHEN qty >= 5 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN price >= 252 THEN 'LARGE' ELSE 'SMALL' END, promo) HAVING COUNT(CASE WHEN promo = 'SPRING10' THEN 1 END) < 1000 ORDER BY spring10_count DESC NULLS LAST
